const jobData = $('Receive Job Data').first().json;
const llmResponse = $input.first().json;

try {
  // Check for API error
  if (llmResponse.error) {
    throw new Error(llmResponse.error.message || 'Claude API error');
  }

  // Extract content from Claude response
  const content = llmResponse.content?.[0]?.text || '';

  // Find JSON in the response
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const quizData = JSON.parse(jsonStr);

  // Build quiz object for API
  const quiz = {
    lesson_id: jobData.body.lesson_id,
    guild_id: jobData.body.guild_id,
    title: quizData.title,
    description: quizData.description,
    instructions: quizData.instructions,
    type: jobData.body.adaptive ? 'adaptive' : 'standard',
    time_limit_seconds: jobData.body.time_limit_seconds || 600,
    passing_score: jobData.body.passing_score || 70,
    questions: quizData.questions.map((q, i) => ({
      text: q.text,
      type: q.type,
      options: q.options,
      correct_answer: q.correct_answer,
      explanation: q.explanation,
      difficulty: q.difficulty || 2,
      order_index: q.order_index || i,
      points: q.points || (q.difficulty === 1 ? 10 : q.difficulty === 3 ? 20 : 15)
    }))
  };

  return {
    json: {
      success: true,
      quiz: quiz,
      job_id: jobData.job_id,
      discord_channel_id: jobData.body.discord_channel_id,
      user_id: jobData.body.user_id,
      bot_token: jobData.body.bot_token
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: e.message,
      job_id: jobData.job_id,
      discord_channel_id: jobData.body.discord_channel_id,
      user_id: jobData.body.user_id,
      bot_token: jobData.body.bot_token
    }
  };
}
